/** "a=1; b=2" ⇒ { a: '1', b: '2' } */
function parseCookieHeader(header) {
  // Write your solution here
  var out = {};
  header.split('; ').forEach(function (p) { var kv = p.split('='); out[kv[0]] = kv[1]; });
  return out;
}

