function readBearer(header) {
  // Write your solution here
  return header.split(' ')[1];
}

solutionCodeJson.code:
// Reference solution
function readBearer(header) {
  if (typeof header !== 'string') return null;
  var m = /^Bearer +([A-Za-z0-9\-._~+/]+=*)$/i.exec(header.trim());
  return m ? m[1] : null;
}
